SELECT * FROM (SELECT CASE WHEN duration_sec >= 391 THEN 'high' WHEN duration_sec >= 102 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, DATE_TRUNC('MONTH', event_time) AS event_month, ROUND((100 * SUM(CASE WHEN event_type = 'search' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_search, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(event_type))) AS event_type_values FROM web_events WHERE page = '/checkout' GROUP BY CASE WHEN duration_sec >= 391 THEN 'high' WHEN duration_sec >= 102 THEN 'mid' ELSE 'low' END, DATE_TRUNC('MONTH', event_time)) AS agg WHERE pct_search >= 40;
